// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value) public {
        vm.assume(value == 10 ether);
        vm.deal(address(this), value);

        uint256 snapshot = vm.snapshot();

        (bool success, ) = address(c).call{value: value}("");
        vm.assume(success);

        assertTrue(c.pastBlockTime() == block.timestamp);

        vm.revertTo(snapshot);
    }
}

